-- ==========================================================================
-- B3 RECUT, ADVANCED TIER: Flare Gas to Value & LPG/CNG (gasvalue)
-- question text brought to petrolord-engines e972ae7 (engines PR #232).
--
-- WHY. Engines #232 recasts engine sentences that broke the owner copy rule
-- (contrastives such as "X, not Y" and "rather than") and gives the queue
-- its facility vocabularies (a CNG forecourt now speaks of dispensers). It
-- moves no value. This LIVE bank quoted the old sentences verbatim, so the
-- quotes are brought to the engine's words. Text only.
--
-- WHAT MOVES. 3 of the 132 questions of this tier, 1 with a changed keyed
-- answer TEXT and 0 with a changed answer INDEX. No ord, no module key, no
-- scope, no option order and no row count moves, so every question id and
-- every learner attempt against it survives.
-- Fields rewritten: 3 explanation, 2 options.
-- Rows (scope, module_key, ord):
--   module m04-the-cascade ord 14: options, explanation
--   module m04-the-cascade ord 15: options, explanation
--   final - ord 35: explanation
--
-- GUARDS. Each row is addressed by its stable identity (app_slug, tier, scope,
-- module_key, ord) and must match EITHER its published text exactly, in which
-- case it is updated, OR the recut text exactly, in which case it is already
-- applied and left alone. Anything else raises and the transaction rolls back.
-- Every update asserts it touched exactly 1 row, and the tier must still hold
-- 132 questions at the end.
--
-- The published strings are the rows migrations/20261013_gv_gasvalue_advanced_deep.sql wrote
-- (APPLIED 2026-09-19), regenerated byte for byte from the banks before this
-- recut. The recut strings are the recut banks. Written by
-- docs/b3-engine-strings-recut/gen_recut.py; see RECUT-gasvalue.json.
--
-- SAFE TO RE-RUN. A second run finds every row already carrying the recut
-- text and updates nothing.
-- ==========================================================================

do $$
declare
  v_state   text;
  v_count   integer;
  v_updated integer := 0;
begin

  -- module m04-the-cascade ord 14: options, explanation
  select case
           when prompt = 'IBAFO''s forecourt is run at 25 buses an hour on 2 dispensers. What does cngDispensing return?' and options = '["REFUSED: The number of bays must be a whole number, one or more.", "An average wait that grows with the 1.2500 utilisation", "An answer: stable false and utilisation 1.2500", "REFUSED: Arrivals, fill time and a dispenser count are required and must be positive."]'::jsonb and answer_index = 2 and explanation = 'SECTION 33: at 25 buses an hour on 2 dispensers the engine gives an answer and no refusal: stable false, utilisation 1.2500, and the message that no average waiting time exists.' then 'old'
           when prompt = 'IBAFO''s forecourt is run at 25 buses an hour on 2 dispensers. What does cngDispensing return?' and options = '["REFUSED: The number of dispensers must be a whole number, one or more.", "An average wait that grows with the 1.2500 utilisation", "An answer: stable false and utilisation 1.2500", "REFUSED: Arrivals, fill time and a dispenser count are required and must be positive."]'::jsonb and answer_index = 2 and explanation = 'At 25 buses an hour on 2 dispensers the engine gives an answer and no refusal: stable false, utilisation 1.2500, and the message that no average waiting time exists.' then 'new'
           else 'other' end
    into v_state
    from public.academy_quiz_questions where app_slug = 'gasvalue' and tier = 'advanced' and scope = 'module' and module_key is not distinct from 'm04-the-cascade'::text and ord = 14;
  if v_state is null then raise exception 'B3 recut gasvalue advanced refused: no row for module m04-the-cascade ord 14'; end if;
  if v_state = 'other' then raise exception 'B3 recut gasvalue advanced refused: module m04-the-cascade ord 14 matches neither its published nor its recut text'; end if;
  if v_state = 'old' then
    update public.academy_quiz_questions
       set prompt = 'IBAFO''s forecourt is run at 25 buses an hour on 2 dispensers. What does cngDispensing return?', options = '["REFUSED: The number of dispensers must be a whole number, one or more.", "An average wait that grows with the 1.2500 utilisation", "An answer: stable false and utilisation 1.2500", "REFUSED: Arrivals, fill time and a dispenser count are required and must be positive."]'::jsonb, answer_index = 2, explanation = 'At 25 buses an hour on 2 dispensers the engine gives an answer and no refusal: stable false, utilisation 1.2500, and the message that no average waiting time exists.'
     where app_slug = 'gasvalue' and tier = 'advanced' and scope = 'module' and module_key is not distinct from 'm04-the-cascade'::text and ord = 14;
    get diagnostics v_count = row_count;
    if v_count <> 1 then raise exception 'B3 recut gasvalue advanced refused: module m04-the-cascade ord 14 updated % rows', v_count; end if;
    v_updated := v_updated + 1;
  end if;

  -- module m04-the-cascade ord 15: options, explanation KEYED ANSWER TEXT CHANGED
  select case
           when prompt = 'cngDispensing is asked for 2.5 dispensers. What comes back?' and options = '["The queue on 2 dispensers, with 2.5 rounded down to a whole number of bays.", "REFUSED: The number of bays must be a whole number, one or more.", "The queue on 3 dispensers, with 2.5 rounded to the nearest whole bay.", "A queue on 2.5 dispensers, the count taken exactly as it was typed."]'::jsonb and answer_index = 1 and explanation = 'SECTION 33''s probe table prints "REFUSED: The number of bays must be a whole number, one or more." for 2.5 dispensers.' then 'old'
           when prompt = 'cngDispensing is asked for 2.5 dispensers. What comes back?' and options = '["The queue on 2 dispensers, with 2.5 rounded down to a whole number of dispensers.", "REFUSED: The number of dispensers must be a whole number, one or more.", "The queue on 3 dispensers, with 2.5 rounded to the nearest whole dispenser.", "A queue on 2.5 dispensers, the count taken exactly as it was typed."]'::jsonb and answer_index = 1 and explanation = 'The probe table prints "REFUSED: The number of dispensers must be a whole number, one or more." for 2.5 dispensers.' then 'new'
           else 'other' end
    into v_state
    from public.academy_quiz_questions where app_slug = 'gasvalue' and tier = 'advanced' and scope = 'module' and module_key is not distinct from 'm04-the-cascade'::text and ord = 15;
  if v_state is null then raise exception 'B3 recut gasvalue advanced refused: no row for module m04-the-cascade ord 15'; end if;
  if v_state = 'other' then raise exception 'B3 recut gasvalue advanced refused: module m04-the-cascade ord 15 matches neither its published nor its recut text'; end if;
  if v_state = 'old' then
    update public.academy_quiz_questions
       set prompt = 'cngDispensing is asked for 2.5 dispensers. What comes back?', options = '["The queue on 2 dispensers, with 2.5 rounded down to a whole number of dispensers.", "REFUSED: The number of dispensers must be a whole number, one or more.", "The queue on 3 dispensers, with 2.5 rounded to the nearest whole dispenser.", "A queue on 2.5 dispensers, the count taken exactly as it was typed."]'::jsonb, answer_index = 1, explanation = 'The probe table prints "REFUSED: The number of dispensers must be a whole number, one or more." for 2.5 dispensers.'
     where app_slug = 'gasvalue' and tier = 'advanced' and scope = 'module' and module_key is not distinct from 'm04-the-cascade'::text and ord = 15;
    get diagnostics v_count = row_count;
    if v_count <> 1 then raise exception 'B3 recut gasvalue advanced refused: module m04-the-cascade ord 15 updated % rows', v_count; end if;
    v_updated := v_updated + 1;
  end if;

  -- final final ord 35: explanation
  select case
           when prompt = 'At 25 buses an hour on 2 dispensers, what does the queue''s message say of the average wait?' and options = '["It is 5.7647 minutes, as at 14 buses an hour.", "No average waiting time exists.", "It is the 6 minutes of one fill.", "It is 1.2500 times the fill time."]'::jsonb and answer_index = 1 and explanation = 'The message: "The rack cannot keep up with arrivals. The queue grows without limit, so no average waiting time exists. Add a bay, load faster, or spread the arrivals."' then 'old'
           when prompt = 'At 25 buses an hour on 2 dispensers, what does the queue''s message say of the average wait?' and options = '["It is 5.7647 minutes, as at 14 buses an hour.", "No average waiting time exists.", "It is the 6 minutes of one fill.", "It is 1.2500 times the fill time."]'::jsonb and answer_index = 1 and explanation = 'The message: "The dispensers cannot keep up with arriving vehicles. The forecourt queue grows without limit, so no average waiting time exists. Add a dispenser, shorten the fill, or spread the arrivals."' then 'new'
           else 'other' end
    into v_state
    from public.academy_quiz_questions where app_slug = 'gasvalue' and tier = 'advanced' and scope = 'final' and module_key is not distinct from null::text and ord = 35;
  if v_state is null then raise exception 'B3 recut gasvalue advanced refused: no row for final final ord 35'; end if;
  if v_state = 'other' then raise exception 'B3 recut gasvalue advanced refused: final final ord 35 matches neither its published nor its recut text'; end if;
  if v_state = 'old' then
    update public.academy_quiz_questions
       set prompt = 'At 25 buses an hour on 2 dispensers, what does the queue''s message say of the average wait?', options = '["It is 5.7647 minutes, as at 14 buses an hour.", "No average waiting time exists.", "It is the 6 minutes of one fill.", "It is 1.2500 times the fill time."]'::jsonb, answer_index = 1, explanation = 'The message: "The dispensers cannot keep up with arriving vehicles. The forecourt queue grows without limit, so no average waiting time exists. Add a dispenser, shorten the fill, or spread the arrivals."'
     where app_slug = 'gasvalue' and tier = 'advanced' and scope = 'final' and module_key is not distinct from null::text and ord = 35;
    get diagnostics v_count = row_count;
    if v_count <> 1 then raise exception 'B3 recut gasvalue advanced refused: final final ord 35 updated % rows', v_count; end if;
    v_updated := v_updated + 1;
  end if;

  select count(*) into v_count from public.academy_quiz_questions where app_slug = 'gasvalue' and tier = 'advanced';
  if v_count <> 132 then raise exception 'B3 recut gasvalue advanced refused: gasvalue advanced holds % questions, expected 132', v_count; end if;
  raise notice 'B3 recut gasvalue advanced: % of 3 rows updated, % already recut', v_updated, 3 - v_updated;
end
$$;
